"""
Builds human-readable, NON-callable-looking semantic keys for archived
observations.

The previous key format — e.g. `get_user_details_user_id_sara_doe_496` —
looked exactly like a function name, so the retrieval RLM repeatedly tried
to "call" the keys as if they were tools, and hallucinated.

This module builds keys as natural noun phrases instead:

    "user details for sara_doe_496 — first/last name, address, email,
     payment methods, list of order ids"

    └──── entity phrase ────┘     └──────── output description ────────┘
     (de-verbed command + params)  (summary of the command's output)

The description half is derived from each command's STATIC
`Signature.Output` field description. Because that description does not
depend on runtime values, it is summarized at most once per command and
cached. Short descriptions are used verbatim; long ones are condensed by
a small LLM call.
"""
from __future__ import annotations

import json
import re

import dspy

from fastworkflow.utils.rlm_logger import rlm_log

# Leading verbs stripped so the key reads as a noun phrase, not an action.
_VERB_PREFIXES = (
    "get_", "find_", "list_", "fetch_", "retrieve_", "show_", "lookup_",
    "search_", "view_", "read_",
)

# Descriptions at or below this length are used verbatim (whitespace-collapsed);
# longer ones go through the LLM summarizer.
_SHORT_DESC_CHARS = 130

# Cache: raw output-description text -> concise summary. Keyed by the raw text
# so identical descriptions across commands share one summary.
_summary_cache: dict[str, str] = {}
_summarizer_lm = None


def _deverb(command_name: str) -> str:
    """`get_user_details` -> `user details`."""
    name = command_name
    for prefix in _VERB_PREFIXES:
        if name.startswith(prefix):
            name = name[len(prefix):]
            break
    return name.replace("_", " ").strip()


def _parse_command(command_str: str) -> tuple[str, list[tuple[str, str]]]:
    """
    Parse `command_name <p1>v1</p1> <p2>v2</p2>` into
    (command_name, [(p1, v1), (p2, v2), ...]).
    """
    command_str = (command_str or "").strip()
    parts = command_str.split(None, 1)
    if not parts:
        return "", []
    command_name = parts[0]
    params: list[tuple[str, str]] = []
    if len(parts) > 1:
        for m in re.finditer(r"<(\w+)>(.*?)</\1>", parts[1], re.DOTALL):
            params.append((m.group(1), m.group(2).strip()))
    return command_name, params


def _get_summarizer_lm():
    """Lazily build the LM used to condense long output descriptions."""
    global _summarizer_lm
    if _summarizer_lm is None:
        from fastworkflow.utils.dspy_utils import get_lm
        _summarizer_lm = get_lm(
            "LLM_CONVERSATION_STORE",
            "LITELLM_API_KEY_CONVERSATION_STORE",
            max_tokens=512,
        )
    return _summarizer_lm


def _summarize_description(raw: str) -> str:
    """Return a concise comma-separated summary of a command output description."""
    raw = (raw or "").strip()
    if not raw:
        return ""
    if raw in _summary_cache:
        return _summary_cache[raw]

    # Short enough — keep verbatim, just normalise whitespace.
    if len(raw) <= _SHORT_DESC_CHARS:
        summary = re.sub(r"\s+", " ", raw).strip().rstrip(".")
        _summary_cache[raw] = summary
        return summary

    # Long — condense with a small LLM call.
    try:
        class _SummarizeOutputDescription(dspy.Signature):
            """Condense a tool's output-field description into a short
            comma-separated list of the KINDS of information it contains.

            Output ONLY the list, e.g.:
              'identifier, status, list of related ids, timestamp'
            No verbs, no full sentences, no leading words like 'contains'.
            Keep it under ~14 words."""
            description: str = dspy.InputField(
                desc="The verbose output-field description of a tool."
            )
            concise: str = dspy.OutputField(
                desc="Short comma-separated list of the information kinds."
            )

        lm = _get_summarizer_lm()
        with dspy.context(lm=lm):
            out = dspy.Predict(_SummarizeOutputDescription)(description=raw)
        summary = re.sub(r"\s+", " ", out.concise or "").strip().rstrip(".")
        if not summary:
            raise ValueError("empty summary")
    except Exception as e:
        rlm_log(f"[SEMANTIC KEY] output-description summary failed ({e}); truncating")
        summary = re.sub(r"\s+", " ", raw)[:_SHORT_DESC_CHARS].rstrip() + "…"

    _summary_cache[raw] = summary
    return summary


def _param_values(params_dict: dict | None) -> list[str]:
    """
    Flatten a params dict into a list of non-empty string values, in insertion
    order. Nested dicts/lists are flattened so their leaf values still appear in
    the key (e.g. an address dict contributes its field values).
    """
    values: list[str] = []

    def _walk(value) -> None:
        if value is None:
            return
        if isinstance(value, dict):
            for v in value.values():
                _walk(v)
        elif isinstance(value, (list, tuple, set)):
            for v in value:
                _walk(v)
        else:
            text = str(value).strip()
            if text:
                values.append(text)

    _walk(params_dict or {})
    return values


def build_semantic_key_from_parts(
    command_name: str,
    params_dict: dict | None = None,
    output_description: str = "",
    step_idx: int = 0,
    session_id: str = "",
) -> str:
    """
    Build a natural-language semantic key from the *structured* command name and
    parameter dict, rather than from the raw `command_name <p>v</p>` string.

    This is the preferred entry point: `command_output.command_name` and
    `command_parameters.model_dump()` are produced by the workflow executor and
    do not depend on the agent LLM correctly enclosing parameters in XML tags,
    so the key stays stable even when the raw command is malformed.

    Example:
      command_name       = "get_user_details"
      params_dict        = {"user_id": "sara_doe_496"}
      output_description = "Detailed user information such as first and last
                            name, address, email, payment methods and the
                            list of order id's"
      ->  "user details for sara_doe_496 — first/last name, address, email,
           payment methods, order ids"

    Falls back to `observation <session> step <n>` if there is no command name.
    """
    if not command_name:
        return f"observation {session_id} step {step_idx}".strip()

    entity = _deverb(command_name)
    param_str = ", ".join(_param_values(params_dict))
    if param_str:
        entity = f"{entity} for {param_str}"

    summary = _summarize_description(output_description)
    return f"{entity} — {summary}" if summary else entity


def build_semantic_key(command_str: str, output_description: str = "",
                       step_idx: int = 0, session_id: str = "") -> str:
    """
    Build a natural-language semantic key for an archived observation by parsing
    the raw `command_name <p>v</p>` string.

    Prefer `build_semantic_key_from_parts` when the structured command name and
    parameter dict are available, since the raw-string parsing here breaks when
    the agent LLM does not enclose parameters in well-formed XML tags.

    Falls back to `observation <session> step <n>` if the command cannot be
    parsed.
    """
    command_name, params = _parse_command(command_str)
    if not command_name:
        return f"observation {session_id} step {step_idx}".strip()

    params_dict = {pname: value for pname, value in params}
    return build_semantic_key_from_parts(
        command_name,
        params_dict,
        output_description=output_description,
        step_idx=step_idx,
        session_id=session_id,
    )


def summarize_description(output_description: str) -> str:
    """Public helper: concise summary of a command output description (cached)."""
    return _summarize_description(output_description)
